package cn.zhuatech.searchai.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class SearchQualityService{public Result evaluate(Request r){double zero=r.zeroResultQueries()*100.0/r.totalQueries();double click=r.clickedQueries()*100.0/r.totalQueries();int score=(int)Math.round(100-zero*.8+(click-50)*.3+r.topThreeClickRate()*.2-r.reformulationRate()*.25-r.staleResultRate()*.2-r.permissionLeakEvents()*30);score=Math.max(0,Math.min(100,score));List<String> actions=new ArrayList<>();if(zero>5)actions.add("扩充同义词、索引范围或内容覆盖");if(r.reformulationRate()>20)actions.add("优化查询理解和排序特征");if(r.staleResultRate()>10)actions.add("提升索引更新频率");if(r.permissionLeakEvents()>0)actions.add("立即修复结果权限过滤");String status=r.permissionLeakEvents()>0?"BLOCK":score<70?"IMPROVE":"HEALTHY";if(actions.isEmpty())actions.add("搜索质量和权限控制处于健康范围");return new Result(Math.round(zero*10)/10.0,Math.round(click*10)/10.0,score,status,actions);}
 public record Request(@Min(1) int totalQueries,@Min(0) int zeroResultQueries,@Min(0) int clickedQueries,@DecimalMin("0") @DecimalMax("100") double topThreeClickRate,@DecimalMin("0") @DecimalMax("100") double reformulationRate,@DecimalMin("0") @DecimalMax("100") double staleResultRate,@Min(0) int permissionLeakEvents){}public record Result(double zeroResultRate,double clickThroughRate,int qualityScore,String status,List<String> actions){} }
